/**
 * Zod validation for bespoke measurements, built from the backend contract.
 *
 * Every range here is read from `fit-contract.json`, which is generated by
 * `manage.py export_fit_contract` from `apps/tailoring/validators.py`. No
 * number in this file is typed by hand, so the frontend cannot drift from the
 * rules the API actually enforces.
 *
 * If the contract is stale, `npm test` fails: `tests/fit-contract.test.ts`
 * checks it against the committed Python ranges.
 */

import { z } from "zod";

import contract from "./fit-contract.json";
import { CM_PER_INCH, type Unit } from "@/lib/units";

export type MeasurementName = keyof typeof contract.measurements;
export type GarmentType = keyof typeof contract.requiredByGarment;

export interface MeasurementRange {
  readonly min: number;
  readonly max: number;
  readonly label: string;
}

/** Plausibility ranges, in inches — the contract's canonical unit. */
export const MEASUREMENT_RANGES = contract.measurements as Record<
  MeasurementName,
  MeasurementRange
>;

export const REQUIRED_BY_GARMENT = contract.requiredByGarment as Record<
  GarmentType,
  readonly MeasurementName[]
>;

export const MEASUREMENT_NAMES = Object.keys(MEASUREMENT_RANGES) as MeasurementName[];

export const GARMENT_TYPES = Object.keys(REQUIRED_BY_GARMENT) as GarmentType[];

/** Range for a measurement, expressed in the unit the user is working in. */
export function rangeIn(name: MeasurementName, unit: Unit): MeasurementRange {
  const range = MEASUREMENT_RANGES[name];
  if (unit === "inch") return range;
  return {
    min: range.min * CM_PER_INCH,
    max: range.max * CM_PER_INCH,
    label: range.label,
  };
}

/**
 * Validator for a single measurement, in inches.
 *
 * The message names the acceptable range rather than saying "invalid". A
 * customer who mistyped 340 for 34 should be able to see why immediately.
 */
export function measurementSchema(name: MeasurementName) {
  const { min, max, label } = MEASUREMENT_RANGES[name];
  return z
    .number({ error: `${label} is required.` })
    .refine((v) => Number.isFinite(v), { message: `${label} must be a number.` })
    .refine((v) => v >= min, {
      message: `${label} must be at least ${min}in — check you are not entering centimetres.`,
    })
    .refine((v) => v <= max, {
      message: `${label} must be at most ${max}in — check you are not entering centimetres.`,
    });
}

/**
 * Cross-field rules, mirrored from `apps/tailoring/serializers.py`.
 *
 * These catch transposed or mismatched entries that are individually
 * plausible — the error mode a per-field range check cannot see.
 */
export const CROSS_FIELD_RULES = [
  {
    id: "underbust_not_above_bust",
    message: "Underbust cannot exceed bust.",
    applies: (v: Partial<Measurements>) =>
      v.underbust !== undefined && v.bust !== undefined,
    valid: (v: Partial<Measurements>) => v.underbust! <= v.bust!,
    fields: ["underbust", "bust"] as const,
  },
  {
    id: "waist_near_bust_and_hip",
    message: "Waist must be within 24 inches of bust and hip.",
    applies: (v: Partial<Measurements>) =>
      v.waist !== undefined && v.bust !== undefined && v.hip !== undefined,
    valid: (v: Partial<Measurements>) =>
      Math.abs(v.waist! - v.bust!) <= 24 && Math.abs(v.waist! - v.hip!) <= 24,
    fields: ["waist", "bust", "hip"] as const,
  },
] as const;

export type Measurements = Partial<Record<MeasurementName, number>>;

/**
 * Build the schema for one garment type: its required measurements are
 * mandatory, every other measurement is optional but still range-checked.
 */
export function fitProfileSchema(garment: GarmentType) {
  const required = new Set<string>(REQUIRED_BY_GARMENT[garment] ?? []);

  const shape: Record<string, z.ZodTypeAny> = {};
  for (const name of MEASUREMENT_NAMES) {
    const base = measurementSchema(name);
    shape[name] = required.has(name) ? base : base.optional();
  }

  return z
    .object(shape)
    .superRefine((value, ctx) => {
      for (const rule of CROSS_FIELD_RULES) {
        if (!rule.applies(value as Measurements)) continue;
        if (rule.valid(value as Measurements)) continue;
        // Attach to every participating field so the message appears next to
        // whichever one the user is looking at.
        for (const field of rule.fields) {
          ctx.addIssue({
            code: "custom",
            message: rule.message,
            path: [field],
          });
        }
      }
    });
}

/** Measurements a given garment cannot be cut without. */
export function requiredFor(garment: GarmentType): readonly MeasurementName[] {
  return REQUIRED_BY_GARMENT[garment] ?? [];
}
